import {LockIcon, MirrorIcon, RepoForkedIcon, RepoIcon} from '@primer/octicons-react'
import {Link, Text} from '@primer/react'
import styles from './RepositoryLabel.module.css'

interface Props {
  /**
   * The octicon key that represents this repository's present state.
   * see Repository#repo_type_icon
   */
  icon: 'repo' | 'lock' | 'repo-forked' | 'mirror' | string
  name: string
  href: string
}

export default function RepositoryLabel({icon, name, href}: Props): JSX.Element {
  const renderRepositoryIcon = (): JSX.Element => {
    switch (icon) {
      case 'repo':
        return <RepoIcon className="fgColor-muted" />
      case 'lock':
        return <LockIcon className="fgColor-muted" />
      case 'repo-forked':
        return <RepoForkedIcon className="fgColor-muted" />
      case 'mirror':
        return <MirrorIcon className="fgColor-muted" />
      default:
        throw new Error(`Unsupported repository icon: ${icon}`)
    }
  }

  return (
    <Link href={href} className={styles.link}>
      {renderRepositoryIcon()}
      &nbsp;
      <Text size="small" className="fgColor-default">
        {name}
      </Text>
    </Link>
  )
}

try{ RepositoryLabel.displayName ||= 'RepositoryLabel' } catch {}