import type {Location} from './location-types'
import type {User} from './user-types'

export interface Alert {
  number: number
  label: string
  token_type: string
  raw_secret: string | null
  resolution: ResolutionType | null
  created_at: string
  resolved_at: string | null
  is_closed: boolean
  token_type_provider: string
  partner_remediation_url: string
  validation_support: ValidationSupport
  first_location_description: string | null
  low_confidence: boolean
  llm_detected: boolean
  multi_repo: boolean
  publicly_leaked: boolean
  validity: TokenVerificationStatus
  // validity_last_checked will be null for standalone tokens that haven't been checked
  // validity_last_checked will be the most recent last checked time for a token's groups if the token is a multipart
  // token
  validity_last_checked: string | null
  async_check_requested_at: string | null
  async_check_in_progress: boolean
  token_groups: TokenGroup[]
  // is_multipart is true if this is a multipart token (e.g. AWS_SECRET, AWS_KEYID, etc.) that TSS supports validity
  // checks for
  is_multipart: boolean
  slug: string
  is_reported: boolean
  feature_flags: AlertFeatureFlags
  is_classic_or_fine_grained_pat: boolean
  first_location_in_actions_file: boolean
}

export interface RelatedAlerts {
  alerts: RelatedAlert[]
  more_exist: boolean
}

export interface RelatedAlert {
  repository_id: number
  repository_owner: string
  repository_name: string
  repository_visibility: string
  repository_icon: string
  number: number
  token_type: string
}

export interface RelatedPublicLeaks {
  leaks: RelatedPublicLeak[]
  more_exist: boolean
}

export interface RelatedPublicLeak {
  repository_id: number
  repository_owner: string
  repository_name: string
  location: Location
}

export interface Timeline {
  events_count: number
  earliest_events: TimelineEvent[]
  latest_events: TimelineEvent[]
  hidden_events: TimelineEvent[]
}

export interface TimelineEvent {
  type: TimelineEventType
  actor: User
  time: string
  resolution?: Resolution
  validity?: {
    validity: TokenVerificationStatus
  }
}

interface Resolution {
  type: ResolutionType
  comment?: string
}

interface ValidationSupport {
  on_demand_checks_supported: boolean
  validity_checks_supported: boolean
}

export interface OnDemandValidation {
  validity: TokenVerificationStatus
  validity_last_checked: string | null
  async_check_requested_at: string | null
  token_groups: TokenGroup[]
  async_check_in_progress: boolean
}

export interface ReportTokenResponse {
  result: ReportResult
  validation: OnDemandValidation
}

export type Validation = OnDemandValidation

export interface TokenGroup {
  members: TokenPart[]
  validity: TokenVerificationStatus
  validity_last_checked: string
}

export interface TokenPart {
  label: string
  number: number
}

export enum AlertStatus {
  OPEN = 'Open',
  CLOSED = 'Closed',
}

export enum TimelineEventType {
  Creation = 'ALERT_CREATION',
  Resolution = 'RESOLUTION',
  Bypass = 'BYPASS',
  Revocation = `REVOCATION`,
  DelegatedBypassRequestOpened = 'DELEGATED_BYPASS_REQUEST_OPENED',
  DelegatedBypassRequestApproved = 'DELEGATED_BYPASS_REQUEST_APPROVED',
  ValidityChange = 'VALIDITY_CHANGE',
  Report = 'REPORT',
  DelegatedClosureRequestOpened = 'DELEGATED_ALERT_CLOSURE_REQUEST_OPENED',
  DelegatedClosureRequestApproved = 'DELEGATED_ALERT_CLOSURE_REQUEST_APPROVED',
  DelegatedClosureRequestRejected = 'DELEGATED_ALERT_CLOSURE_REQUEST_REJECTED',
}

export enum ResolutionType {
  Revoked = 'revoked',
  Reopened = 'reopened',
  FalsePositive = 'false_positive',
  UsedInTests = 'used_in_tests',
  WontFix = 'wont_fix',
  PatternEdited = 'pattern_edited',
  PatternDeleted = 'pattern_deleted',
  HiddenByConfig = 'hidden_by_config',
}

export enum TokenVerificationStatus {
  TOKEN_VALIDITY_ACTIVE = 'TOKEN_VALIDITY_ACTIVE',
  TOKEN_VALIDITY_REVOKED = 'TOKEN_VALIDITY_REVOKED',
  TOKEN_VALIDITY_INACTIVE = 'TOKEN_VALIDITY_INACTIVE',
  TOKEN_VALIDITY_UNKNOWN = 'TOKEN_VALIDITY_UNKNOWN',
  TOKEN_VALIDITY_UNVERIFIABLE = 'TOKEN_VALIDITY_UNVERIFIABLE',
}

export enum ReportResult {
  REPORT_RESULT_UNKNOWN = 'UNKNOWN',
  REPORT_RESULT_REVOKED = 'REVOKED',
  REPORT_RESULT_ALREADY_REVOKED = 'ALREADY_REVOKED',
  REPORT_RESULT_TOKEN_NOT_FOUND = 'TOKEN_NOT_FOUND',
}

export interface AlertFeatureFlags {
  [key: string]: boolean
}

export function showAIAssistedRemediationGuidance(alert: Alert) {
  const showRemediationStep = alert.feature_flags?.ai_assisted_remediation_guidance_for_gh_pats

  if (!showRemediationStep) {
    return false
  }

  if (!alert.is_classic_or_fine_grained_pat || !alert.first_location_in_actions_file) {
    return false
  }

  return true
}

export interface PermissionsCollection {
  groups: {
    [group: string]: Permission[]
  }
  group_label: string
  value_label: string
}

export interface Permission {
  // for PATv1, the value will be the scope (ie "repo" or "repo:read" or "admin:org")
  // for PATv2, the value will be the target (ie "metadata")
  value: string

  // for PATv1, the group will be a display version of the parent scope (ie "repo" or "org")
  // for PATv2, the group will be a display version of the permission ("Read" or "Read and Write")
  group: string
  deleted: boolean
}
