import {Header, Label, Link} from '@primer/react'
import {showAIAssistedRemediationGuidance, type Alert} from '../../../types/alert-types'
import {RevocationStep} from './steps/Revocation'
import {GenerationStep} from './steps/Generation'
import type {Repository} from '../../../types/repo-types'
import {AutofixAISuggestion} from './steps/AutofixAISuggestion'
import type {RepoBlobLocation} from '../../../types/location-types'
import {RemediationStepTemplate} from './RemediationStepTemplate'
import {verificationStatusInactive} from '../../shared/VerificationStatus'

export function Guidance({
  alert,
  repository,
  hasMetadata,
  firstLocation,
}: {
  alert: Alert
  repository: Repository
  hasMetadata: boolean
  firstLocation: RepoBlobLocation | undefined
}) {
  if (!showAIAssistedRemediationGuidance(alert)) {
    return null
  }

  return (
    <div>
      <Header className="bgColor-default pt-3 pl-0 pr-0 pb-0 mb-3">
        <Header.Item full className="f3 text-semibold fgColor-default">
          Remediation
        </Header.Item>
        <Header.Item>
          <Label variant="success">Private preview</Label>
        </Header.Item>
        <Header.Item>
          <Link href={'https://gh.io/copilot-secret-scanning-feedback'}>Give feedback</Link>
        </Header.Item>
      </Header>

      <RemediationStepTemplate
        isDefaultExpanded={!verificationStatusInactive(alert.validity)}
        stepIndex={1}
        headingText="Revoke the secret"
        onExpand={() => {}}
        isFirstStep
        isLastStep={false}
      >
        <RevocationStep alert={alert} repository={repository} hasMetadata={hasMetadata} />
      </RemediationStepTemplate>

      <RemediationStepTemplate
        isDefaultExpanded
        stepIndex={2}
        headingText="Generate the secret"
        onExpand={() => {}}
        isFirstStep={false}
        isLastStep={false}
      >
        <GenerationStep alert={alert} repository={repository} hasMetadata={hasMetadata} />
      </RemediationStepTemplate>

      <RemediationStepTemplate
        isDefaultExpanded
        stepIndex={3}
        headingText="Rotate the secret"
        onExpand={() => {}}
        isFirstStep={false}
        isLastStep
      >
        <AutofixAISuggestion alert={alert} repository={repository} firstLocation={firstLocation} />
      </RemediationStepTemplate>

      <div className="text-small fgColor-muted pt-1 pb-1">
        Copilot is powered by AI and may make mistakes. Always verify output.{' '}
        <Link inline href={'https://gh.io/secret-remediation-docs'}>
          Learn more
        </Link>
      </div>
    </div>
  )
}

try{ Guidance.displayName ||= 'Guidance' } catch {}