import type {PermissionsCollection, Permission} from '../../../types/alert-types'
import styles from './PermissionsTable.module.css'

export function PermissionsTable({collection, title}: {collection?: PermissionsCollection; title?: string}) {
  if (!collection || Object.keys(collection?.groups ?? {}).length === 0) {
    return null
  }

  return (
    <>
      {title && <div className="mb-1 fgColor-muted text-small text-bold">{title}</div>}
      <div
        data-testid="secret-scanning-permissions-table"
        className="d-table border rounded-1 width-full table-fixed borderColor-default"
      >
        <span className="d-table-cell p-2 col-3 float-left text-semibold fgColor-muted bgColor-muted border-bottom">
          {collection.group_label}
        </span>
        <span className="d-table-cell p-2 col-9 float-left text-semibold fgColor-muted bgColor-muted border-bottom">
          {collection.value_label}
        </span>
        <div>
          {Object.entries(collection?.groups ?? []).map(([group, permissions], index) => {
            const borderTop = index === 0 ? '' : 'border-top'
            return (
              <div key={group}>
                <span className={`d-table-cell p-2 col-3 float-left text-bold bgColor-default ${borderTop}`}>
                  {group}
                </span>
                <span className={`d-table-cell p-2 col-9 float-left bgColor-default ${borderTop}`}>
                  {permissions.map((permission, permissionIndex) => (
                    <PermissionValue
                      key={permission.value}
                      permission={permission}
                      isLast={permissionIndex >= permissions.length - 1}
                    />
                  ))}
                </span>
              </div>
            )
          })}
        </div>
      </div>
    </>
  )
}

function PermissionValue({permission, isLast = true}: {permission: Permission; isLast?: boolean}) {
  if (permission.deleted) {
    // eslint-disable-next-line prettier/prettier
    return (<><del className={styles.deletedPermission}>{permission.value}</del>{isLast ? '' : ', '}</>)
  }
  // eslint-disable-next-line prettier/prettier
  return (<>{permission.value}{isLast ? '' : ', '}</>)
}

try{ PermissionsTable.displayName ||= 'PermissionsTable' } catch {}
try{ PermissionValue.displayName ||= 'PermissionValue' } catch {}