import {
  secretScanningAdversarialAuditPath,
  secretScanningTokenPermissionsPath,
  secretScanningWorkflowAuditPath,
} from '../../../../paths'
import type {Alert, PermissionsCollection} from '../../../../types/alert-types'
import {useQuery} from '@tanstack/react-query'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {Repository} from '../../../../types/repo-types'
import {Banner, SkeletonText} from '@primer/react/experimental'
import {PermissionsTable} from '../PermissionsTable'
import {AIRemediationFeedback} from './components/AIRemediationFeedback'
import {verificationStatusInactive} from '../../../shared/VerificationStatus'

function Revocation({
  adversarialAudit,
  isAdversarialAuditLoading,
  workflowAudit,
  isWorkflowAuditLoading,
  permissions,
  acceptFeedback,
}: {
  adversarialAudit: string
  isAdversarialAuditLoading: boolean
  workflowAudit: string
  isWorkflowAuditLoading: boolean
  permissions?: PermissionsCollection
  acceptFeedback: boolean
}) {
  return (
    <>
      <div className="pt-2 pl-3 pr-3 pb-3" data-testid="secret-scanning-revocation-step">
        <p className="f5 text-semibold mb-2">What could this token be used for?</p>
        {isAdversarialAuditLoading ? <SkeletonText lines={3} /> : <p>{adversarialAudit}</p>}

        <p className="f5 text-semibold mb-2">What could break if I revoke the secret?</p>
        {isWorkflowAuditLoading ? <SkeletonText lines={3} /> : <p>{workflowAudit}</p>}

        <PermissionsTable collection={permissions} title={'Token permissions'} />

        <br />

        <Banner
          variant="info"
          description={
            <>Regenerate a new token and update references before revoking the old one to prevent service disruption.</>
          }
        >
          <Banner.Title />
        </Banner>

        <br />
        {acceptFeedback && <AIRemediationFeedback stepName="revocation" />}
      </div>
    </>
  )
}

export function RevocationStep({
  alert,
  repository,
  hasMetadata,
}: {
  alert: Alert
  repository: Repository
  hasMetadata: boolean
}) {
  const aiAdversarialAuditUrl = secretScanningAdversarialAuditPath(
    repository.owner_display_login,
    repository.name,
    alert.number,
  )

  const permissionsPath = secretScanningTokenPermissionsPath(
    repository.owner_display_login,
    repository.name,
    alert.number,
  )

  const workflowAuditPath = secretScanningWorkflowAuditPath(
    repository.owner_display_login,
    repository.name,
    alert.number,
  )

  const {
    isLoading: isAdversarialAuditLoading,
    data: {audit: adversarialAudit, fallback: isAdversarialAuditFallback} = {},
  } = useQuery({
    queryKey: [aiAdversarialAuditUrl],
    staleTime: Infinity,
    queryFn: async () => {
      const adversarialAuditFallback =
        "View this token's permissions to determine potential actions an adversary could take with it."
      try {
        const result = await verifiedFetch(aiAdversarialAuditUrl, {
          method: 'get',
        })
        if (!result.ok) {
          return {audit: adversarialAuditFallback, fallback: true}
        }
        const res = await result.json()
        return {audit: res.message, fallback: false}
      } catch {
        return {audit: adversarialAuditFallback, fallback: true}
      }
    },
    enabled: hasMetadata,
  })

  const {isLoading: isWorkflowAuditLoading, data: {audit: workflowAudit, fallback: isWorkflowAuditFallback} = {}} =
    useQuery({
      queryKey: ['secret-scanning', workflowAuditPath],
      staleTime: Infinity,
      queryFn: async () => {
        const workflowAuditFallback =
          'View audit log events for this token to see what workflows might break upon rotation.'
        try {
          const result = await verifiedFetch(workflowAuditPath, {
            method: 'get',
          })
          if (!result.ok) {
            return {audit: workflowAuditFallback, fallback: true}
          }
          const res = await result.json()
          return {audit: res.message, fallback: false}
        } catch {
          return {audit: workflowAuditFallback, fallback: true}
        }
      },
      enabled: hasMetadata,
    })

  const {data: permissions} = useQuery({
    queryKey: [permissionsPath],
    staleTime: Infinity,
    queryFn: async () => {
      const result = await verifiedFetch(permissionsPath, {method: 'get'})
      if (!result.ok) {
        return {}
      }
      const res = await result.json()
      return res.permissions
    },
    enabled: hasMetadata && !!alert.feature_flags?.secret_scanning_display_alert_permissions,
  })

  if (hasMetadata) {
    return (
      <Revocation
        isAdversarialAuditLoading={isAdversarialAuditLoading}
        adversarialAudit={adversarialAudit}
        isWorkflowAuditLoading={isWorkflowAuditLoading}
        workflowAudit={workflowAudit}
        permissions={permissions}
        acceptFeedback={!isAdversarialAuditFallback || !isWorkflowAuditFallback}
      />
    )
  }

  if (verificationStatusInactive(alert.validity)) {
    return (
      <div className="pr-3 pl-3 pb-3 pt-2" data-testid="secret-scanning-revocation-step-no-metadata">
        The incident refers to a GitHub Personal Access Token exposed within a GitHub Actions workflow. This secret is
        no longer active. You should still consider rotating the token if necessary and review logs for potential abuse
        of this token.
      </div>
    )
  }

  return (
    <div className="pr-3 pl-3 pb-3 pt-2" data-testid="secret-scanning-revocation-step-no-metadata">
      The incident refers to a GitHub Personal Access Token exposed within a GitHub Actions workflow. This secret may
      not be active. You should still consider rotating the token if necessary and review logs for potential abuse of
      this token.
    </div>
  )
}

try{ Revocation.displayName ||= 'Revocation' } catch {}
try{ RevocationStep.displayName ||= 'RevocationStep' } catch {}