import {Ago} from '@github-ui/ago'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {
  type Timeline as TimelineData,
  type TimelineEvent,
  TimelineEventType,
  ResolutionType,
  TokenVerificationStatus,
} from '../../types/alert-types'
import type {User} from '../../types/user-types'
import {Timeline, Text, Box, Button} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {
  ShieldIcon,
  ShieldCheckIcon,
  SyncIcon,
  MarkGithubIcon,
  ShieldSlashIcon,
  AlertIcon,
  CommentIcon,
  CheckCircleIcon,
  SkipIcon,
  type Icon,
  XIcon,
} from '@primer/octicons-react'
import {Fragment, useState} from 'react'
import {resolutionText} from '../../helper'
import styles from './AlertTimeline.module.css'

export function AlertTimeline({timeline}: {timeline: TimelineData}) {
  const [loadAllEvents, setLoadAllEvents] = useState(false)

  function handleLoadAllClick() {
    setLoadAllEvents(true)
  }

  return <Timeline clipSidebar>{getTimelineItems(timeline, loadAllEvents, handleLoadAllClick)}</Timeline>
}

function getTimelineItems(timeline: TimelineData, loadAllEvents: boolean, handleLoadAllClick: () => void) {
  const timelineItems = []

  // Push the earliest events in the timeline.
  if (timeline.earliest_events.length > 0) {
    timelineItems.push(
      timeline.earliest_events.map((event: TimelineEvent, index: number) =>
        getTimelineItem(event, `timeline-earliest-item-${index}`),
      ),
    )
  }

  // If the number of events is greater than a set limit, then show a "Load all..." button and
  // don't show hidden events until user clicks on the button.
  if (timeline.hidden_events.length > 0) {
    if (loadAllEvents) {
      timelineItems.push(
        timeline.hidden_events.map((event: TimelineEvent, index: number) =>
          getTimelineItem(event, `timeline-hidden-item-${index}`),
        ),
      )
    } else {
      timelineItems.push(
        <Box key={'load-all'} sx={{display: 'flex', justifyContent: 'center', py: 4}}>
          <Box
            sx={{
              display: 'inline-flex',
              flexDirection: 'column',
              borderColor: 'border.default',
              borderWidth: 1,
              borderRadius: 2,
              borderStyle: 'solid',
              px: 3,
              py: 2,
            }}
          >
            <Text sx={{fontWeight: 'bold', fontSize: 'small', mb: 1, color: 'fg.muted'}}>
              {timeline.hidden_events.length} hidden item{timeline.hidden_events.length > 1 ? 's' : ''}
            </Text>
            <Button variant="invisible" size="small" onClick={handleLoadAllClick}>
              Load all...
            </Button>
          </Box>
        </Box>,
      )
    }
  }

  // Push the latest events in the timeline.
  if (timeline.latest_events.length > 0) {
    timelineItems.push(
      timeline.latest_events.map((event: TimelineEvent, index: number) =>
        getTimelineItem(event, `timeline-latest-item-${index}`),
      ),
    )
  }

  return timelineItems
}

function getTimelineItem(event: TimelineEvent, index: string) {
  switch (event.type) {
    case TimelineEventType.Creation:
      return (
        <TimelineItem key={index} badgeBgColor="success.emphasis" iconColor="fgColor-onEmphasis" icon={ShieldIcon}>
          <TimelineItemBody event={event} action="opened this alert" isGitHubActor />
        </TimelineItem>
      )
    case TimelineEventType.Resolution:
      if (!event.resolution) return null
      if (event.resolution.type === ResolutionType.Reopened) {
        return (
          <Fragment key={index}>
            {/* NOTE - Timeline.Break needs to be a sibling with the Timeline.Item behind it */}
            {/* for the CSS sibling selector to apply correctly. */}
            <Timeline.Break className={`${styles.timelineBreak}`} />
            <TimelineItem badgeBgColor="success.emphasis" iconColor="fgColor-onEmphasis" icon={SyncIcon}>
              <TimelineItemBody event={event} action="reopened this" />
            </TimelineItem>
          </Fragment>
        )
      } else {
        let badgeBgColor: string | undefined = undefined
        let iconColor = 'fgColor-muted'
        let icon = ShieldSlashIcon
        if (event.resolution.type === ResolutionType.Revoked) {
          badgeBgColor = 'done.emphasis'
          iconColor = 'fgColor-onEmphasis'
          icon = ShieldCheckIcon
        }
        return (
          <TimelineItem key={index} badgeBgColor={badgeBgColor} iconColor={iconColor} icon={icon}>
            <TimelineItemBody event={event} action={`closed this as ${resolutionText(event.resolution.type)}`} />
          </TimelineItem>
        )
      }
    case TimelineEventType.Bypass:
      return (
        <TimelineItem key={index} iconColor="fgColor-muted" icon={AlertIcon}>
          <TimelineItemBody event={event} action="bypassed push protection" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedBypassRequestOpened:
      return (
        <TimelineItem key={index} iconColor="fgColor-muted" icon={CommentIcon}>
          <TimelineItemBody event={event} action="requested bypass privileges" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedBypassRequestApproved:
      return (
        <TimelineItem key={index} iconColor="fgColor-muted" icon={CheckCircleIcon}>
          <TimelineItemBody event={event} action="approved a bypass" />
        </TimelineItem>
      )
    case TimelineEventType.ValidityChange:
      return ValidityChangeTimelineEvent({event, index})
    case TimelineEventType.Report:
      return (
        <TimelineItem key={index} iconColor="fgColor-muted" icon={ShieldCheckIcon}>
          <TimelineItemBody event={event} action="reported this secret" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedClosureRequestOpened:
      return (
        <TimelineItem key={index} iconColor="fgColor-muted" icon={CommentIcon}>
          <TimelineItemBody event={event} action="requested to dismiss this" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedClosureRequestApproved:
      return (
        <TimelineItem key={index} iconColor="fgColor-muted" icon={CheckCircleIcon}>
          <TimelineItemBody event={event} action="approved dismissal" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedClosureRequestRejected:
      return (
        <TimelineItem key={index} iconColor="fgColor-muted" icon={XIcon}>
          <TimelineItemBody event={event} action="denied dismissal" />
        </TimelineItem>
      )
  }
}

function TimelineItem({
  badgeBgColor,
  iconColor,
  icon,
  children,
}: {
  badgeBgColor?: string
  iconColor: string
  icon: Icon
  children: React.ReactNode
}) {
  return (
    <Timeline.Item className={`${styles.timelineItem}`}>
      <Timeline.Badge sx={{backgroundColor: badgeBgColor}}>
        <Octicon icon={icon} className={iconColor} />
      </Timeline.Badge>
      <Timeline.Body>{children}</Timeline.Body>
    </Timeline.Item>
  )
}

function TimelineItemBody({
  event,
  action,
  isGitHubActor = false,
}: {
  event: TimelineEvent
  action: string
  isGitHubActor?: boolean
}) {
  const comment = event.resolution?.comment
  return (
    <>
      <Box sx={{display: 'flex', alignItems: 'center'}}>
        {isGitHubActor ? (
          <>
            <Octicon icon={MarkGithubIcon} />
            <Text sx={{fontWeight: 'bold', ml: 1}}>GitHub</Text>
          </>
        ) : (
          <ActorComponent actor={event.actor} />
        )}
        <Text sx={{ml: 1}}>{action}</Text>
        <Ago sx={{ml: 1}} timestamp={new Date(event.time)} />
      </Box>
      {comment && (
        <div data-testid={'resolution-comment'} className={`${styles.timelineComment} d-flex flex-items-center mt-1`}>
          <Octicon icon={CommentIcon} size={12} sx={{ml: 1, color: 'fg.muted', verticalAlign: 'middle'}} />
          <Text sx={{fontSize: 12, ml: 1}}>{comment}</Text>
        </div>
      )}
    </>
  )
}

function ValidityChangeTimelineEvent({event, index}: {event: TimelineEvent; index: string}) {
  const isInactive =
    event.validity?.validity === TokenVerificationStatus.TOKEN_VALIDITY_INACTIVE ||
    event.validity?.validity === TokenVerificationStatus.TOKEN_VALIDITY_REVOKED
  const isUnknown =
    event.validity?.validity === TokenVerificationStatus.TOKEN_VALIDITY_UNKNOWN ||
    event.validity?.validity === TokenVerificationStatus.TOKEN_VALIDITY_UNVERIFIABLE

  // If active, danger.fg and 'active', otherwise use the conditions below
  let badgeBgColor = 'danger.fg'
  let icon = AlertIcon
  let validityText = 'GitHub verified this secret is active'
  if (isInactive) {
    badgeBgColor = 'fg.muted'
    icon = SkipIcon
    validityText = 'GitHub verified this secret is inactive'
  }
  if (isUnknown) {
    badgeBgColor = 'attention.fg'
    icon = AlertIcon
    validityText = 'GitHub is unable to determine the validity of this secret'
  }

  return (
    <TimelineItem key={index} badgeBgColor={badgeBgColor} iconColor="fgColor-onEmphasis" icon={icon}>
      <span className="ml-1">{validityText}</span>
      <Ago sx={{ml: 1}} timestamp={new Date(event.time)} />
    </TimelineItem>
  )
}

function ActorComponent({actor}: {actor: User}) {
  if (actor) {
    return (
      <div data-testid={'actor-component'}>
        {actor.avatar_url && <GitHubAvatar size={16} src={actor.avatar_url} />}
        <Text sx={{ml: 1, fontWeight: 'bold'}}>{actor.display_login}</Text>
      </div>
    )
  } else return null
}

try{ AlertTimeline.displayName ||= 'AlertTimeline' } catch {}
try{ TimelineItem.displayName ||= 'TimelineItem' } catch {}
try{ TimelineItemBody.displayName ||= 'TimelineItemBody' } catch {}
try{ ValidityChangeTimelineEvent.displayName ||= 'ValidityChangeTimelineEvent' } catch {}
try{ ActorComponent.displayName ||= 'ActorComponent' } catch {}