import {Box, Text} from '@primer/react'
import styles from './TokenMetadataSection.module.css'

export function TokenMetadataSection({children, sectionName}: {children: React.ReactNode; sectionName: string}) {
  const BoxObjectProps = {
    display: 'flex',
    flexDirection: 'column',
    paddingBottom: 3,
  }

  return (
    <Box sx={BoxObjectProps} className={styles.section}>
      <Text sx={{color: 'fg.muted', fontSize: 'small', fontWeight: 'bold'}}>{sectionName}</Text>
      {children}
    </Box>
  )
}

try{ TokenMetadataSection.displayName ||= 'TokenMetadataSection' } catch {}